style.css:
@-moz-document domain("discord.com") {
/* Clears Discord's heavy dark/light background boxes */
  html, body, #app-mount, 
  [class*="app_"], [class*="bg_"], 
  [class*="layer_"], [class*="layers_"], 
  [class*="appInner_"], [class*="container_"], 
  [class*="chat_"], [class*="sidebar_"], 
  [class*="panels_"], [class*="chatMain_"],
  main[class*="chatContent_"], [class*="members_"] {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Injects the actual Cinnamoroll character picture */
  html {
    background-image: url('https://imgur.com') !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
  }

  /* Makes panels highly translucent so you can see through them to the character */
  main[class*="chatContent_"] {
    background-color: rgba(255, 255, 255, 0.45) !important;
    backdrop-filter: blur(2px) !important;
  }
  
  [class*="sidebar_"] {
    background-color: rgba(225, 242, 254, 0.5) !important;
  }

  [class*="members_"] {
    background-color: rgba(255, 255, 255, 0.3) !important;
  }
}
